// T-4232~T-4281: external widget retry, freshness, health ordering and queue lifecycle contracts.
test("health rank orders every known state", () => assert.deepEqual(model.EXTERNAL_WIDGET_HEALTH.slice().sort((a, b) => model.externalWidgetHealthRank(a) - model.externalWidgetHealthRank(b)), ["error", "offline", "stale", "unknown", "cached", "healthy"]));
test("health comparison returns zero for equal states", () => assert.equal(model.compareExternalWidgetHealth("stale", "stale"), 0));
test("health comparison ranks cached above unknown", () => assert.equal(model.compareExternalWidgetHealth("cached", "unknown"), 1));
test("health comparison normalizes malformed values", () => assert.equal(model.compareExternalWidgetHealth("bad", "unknown"), 0));
test("freshness without timestamp is unknown", () => assert.equal(model.resolveExternalWidgetFreshness({moduleId: "x"}, 60000, 1000), "unknown"));
test("freshness at ttl boundary is fresh", () => assert.equal(model.resolveExternalWidgetFreshness({timestamp: 1000}, 60000, 61000), "fresh"));
test("freshness just past ttl is aging", () => assert.equal(model.resolveExternalWidgetFreshness({timestamp: 1000}, 60000, 61001), "aging"));
test("freshness at twice ttl is aging", () => assert.equal(model.resolveExternalWidgetFreshness({timestamp: 1000}, 60000, 121000), "aging"));
test("freshness past twice ttl is expired", () => assert.equal(model.resolveExternalWidgetFreshness({timestamp: 1000}, 60000, 121001), "expired"));
test("snapshot age clamps future timestamps to zero", () => assert.equal(model.externalWidgetSnapshotAge({timestamp: 2000}, 1000), 0));
test("retry attempt normalizes negative values", () => assert.equal(model.normalizeExternalWidgetRetryAttempt(-4), 0));
test("retry attempt truncates fractional values", () => assert.equal(model.normalizeExternalWidgetRetryAttempt(2.9), 2));
test("retry attempt rejects non numeric values", () => assert.equal(model.normalizeExternalWidgetRetryAttempt("nope"), 0));
test("retry delay clamps a tiny base", () => assert.equal(model.externalWidgetRetryDelay(0, 1), 250));
test("retry delay clamps a huge base", () => assert.equal(model.externalWidgetRetryDelay(0, 999999), 30000));
test("retry delay is capped at five minutes", () => assert.equal(model.externalWidgetRetryDelay(8, 30000), 300000));
test("retry delay normalizes negative attempt", () => assert.equal(model.externalWidgetRetryDelay(-1, 1000), 1000));
test("healthy widget is not retryable at any attempt", () => assert.equal(model.shouldRetryExternalWidget("healthy", 0), false));
test("offline widget is retryable before max attempt", () => assert.equal(model.shouldRetryExternalWidget("offline", 7), true));
test("offline widget stops retrying at max attempt", () => assert.equal(model.shouldRetryExternalWidget("offline", 8), false));
test("unknown health is never retryable", () => assert.equal(model.shouldRetryExternalWidget("unknown", 0), false));
test("retry plan carries normalized module id", () => assert.equal(model.buildExternalWidgetRetryPlan({moduleId: " x ", health: "stale"}, {now: 10}).moduleId, "x"));
test("retry plan computes delay and retryAt", () => assert.deepEqual(model.buildExternalWidgetRetryPlan({moduleId: "x", health: "error"}, {attempt: 2, baseDelay: 500, now: 100}), {version: 1, moduleId: "x", attempt: 2, retryable: true, delay: 2000, retryAt: 2100}));
test("non retryable plan has zero retryAt", () => assert.equal(model.buildExternalWidgetRetryPlan({moduleId: "x", health: "healthy"}, {now: 100}).retryAt, 0));
test("retry plan clamps supplied attempt", () => assert.equal(model.buildExternalWidgetRetryPlan({health: "stale"}, {attempt: 99}).attempt, 8));
