test("error classifier recognizes network wording", () => assert.equal(model.classifyExternalWidgetError("network unavailable"), "network"));
test("error classifier recognizes response wording", () => assert.equal(model.classifyExternalWidgetError("invalid JSON response"), "response"));
test("empty error classifier returns none", () => assert.equal(model.classifyExternalWidgetError(""), "none"));
test("next refresh without timestamp uses current time", () => assert.equal(model.nextExternalWidgetRefreshAt({moduleId: "x"}, 60000, 1234), 1234));
test("next refresh never returns a time before now", () => assert.equal(model.nextExternalWidgetRefreshAt({timestamp: 1}, 60000, 1234), 60001));
test("refresh due is true at exact expiry", () => assert.equal(model.isExternalWidgetRefreshDue({timestamp: 1000}, 60000, 61000), true));
test("refresh due is false one millisecond before expiry", () => assert.equal(model.isExternalWidgetRefreshDue({timestamp: 1000}, 60000, 60999), false));
