test("snapshot compatibility rejects missing module id", () => assert.equal(model.isExternalWidgetSnapshotCompatible({version: 1, health: "healthy", action: "add"}), false));
test("snapshot compatibility rejects oversized module id", () => assert.equal(model.isExternalWidgetSnapshotCompatible({version: 1, moduleId: "x".repeat(97), health: "healthy", action: "add"}), false));
test("snapshot compatibility rejects unknown health", () => assert.equal(model.isExternalWidgetSnapshotCompatible({version: 1, moduleId: "x", health: "wat", action: "add"}), false));
test("snapshot compatibility rejects unknown action", () => assert.equal(model.isExternalWidgetSnapshotCompatible({version: 1, moduleId: "x", health: "healthy", action: "wat"}), false));
test("snapshot serialization is deterministic", () => assert.equal(model.serializeExternalWidgetSnapshot({moduleId: "x", health: "healthy"}), model.serializeExternalWidgetSnapshot({health: "healthy", moduleId: "x"})));
test("snapshot parser normalizes valid payload", () => assert.equal(model.parseExternalWidgetSnapshot('{"version":1,"moduleId":"x","health":"healthy","action":"add"}').moduleId, "x"));
test("snapshot parser falls back for wrong version", () => assert.equal(model.parseExternalWidgetSnapshot('{"version":2,"moduleId":"x","health":"healthy","action":"add"}').moduleId, ""));
test("snapshot diff ignores timestamp-only changes", () => assert.equal(model.diffExternalWidgetSnapshots({moduleId: "x", timestamp: 1}, {moduleId: "x", timestamp: 2}).changed, false));
test("snapshot diff reports health change only", () => { const diff = model.diffExternalWidgetSnapshots({moduleId: "x", health: "healthy"}, {moduleId: "x", health: "stale"}); assert.deepEqual({changed: diff.changed, healthChanged: diff.healthChanged, statusChanged: diff.statusChanged}, {changed: true, healthChanged: true, statusChanged: false}); });
test("snapshot diff uses current module id first", () => assert.equal(model.diffExternalWidgetSnapshots({moduleId: "a"}, {moduleId: "b"}).moduleId, "b"));
test("snapshot transition marks unchanged snapshots", () => assert.equal(model.buildExternalWidgetTransition({moduleId: "x"}, {moduleId: "x"}).type, "unchanged"));
test("snapshot transition marks action changes", () => assert.equal(model.buildExternalWidgetTransition({moduleId: "x", action: "add"}, {moduleId: "x", action: "retry"}).type, "changed"));
test("history normalizer keeps only bounded newest records", () => assert.equal(model.normalizeExternalWidgetHistory(Array.from({length: 20}, (_, i) => ({moduleId: `m${i}`}))).length, 16));
test("history normalizer drops records without module id", () => assert.deepEqual(model.normalizeExternalWidgetHistory([{health: "healthy"}]), []));
test("append history ignores empty snapshot", () => assert.equal(model.appendExternalWidgetSnapshot([{moduleId: "x"}], {}).length, 1));
test("append history appends newest snapshot", () => assert.equal(model.appendExternalWidgetSnapshot([{moduleId: "x"}], {moduleId: "y"}).at(-1).moduleId, "y"));
test("append history evicts oldest record at capacity", () => { const history = Array.from({length: 16}, (_, i) => ({moduleId: `m${i}`})); assert.equal(model.appendExternalWidgetSnapshot(history, {moduleId: "new"})[0].moduleId, "m1"); });
test("trim history applies a smaller positive limit", () => assert.equal(model.trimExternalWidgetHistory([{moduleId: "a"}, {moduleId: "b"}], 1).length, 1));
test("trim history falls back to bounded default for invalid limit", () => assert.equal(model.trimExternalWidgetHistory([{moduleId: "a"}], "bad").length, 1));
test("latest history selects requested module", () => assert.equal(model.latestExternalWidgetSnapshot([{moduleId: "a"}, {moduleId: "b"}], "b").moduleId, "b"));
test("latest history returns null for missing module", () => assert.equal(model.latestExternalWidgetSnapshot([{moduleId: "a"}], "b"), null));
test("latest history without module selects final record", () => assert.equal(model.latestExternalWidgetSnapshot([{moduleId: "a"}, {moduleId: "b"}]).moduleId, "b"));
test("history selector filters by health", () => assert.deepEqual(model.selectExternalWidgetHistory([{moduleId: "a", health: "healthy"}, {moduleId: "b", health: "stale"}], "stale").map((x) => x.moduleId), ["b"]));
test("history selector applies a bounded limit", () => assert.equal(model.selectExternalWidgetHistory(Array.from({length: 5}, (_, i) => ({moduleId: `m${i}`, health: "stale"})), "stale", 2).length, 2));
test("history summary exposes latest record", () => assert.equal(model.summarizeExternalWidgetHistory([{moduleId: "x", health: "healthy"}]).latest.moduleId, "x"));
test("history summary counts each health", () => assert.equal(model.summarizeExternalWidgetHistory([{moduleId: "x", health: "healthy"}, {moduleId: "y", health: "error"}]).counts.error, 1));
test("history summary has zero latest for empty history", () => assert.equal(model.summarizeExternalWidgetHistory([]).latest, null));
test("snapshot merge accepts scalar and array inputs", () => assert.equal(model.mergeExternalWidgetSnapshots({moduleId: "x"}, [{moduleId: "y"}]).length, 2));
test("snapshot merge replaces equal timestamp with later source", () => assert.equal(model.mergeExternalWidgetSnapshots([{moduleId: "x", status: "old", timestamp: 1}], [{moduleId: "x", status: "new", timestamp: 1}])[0].status, "new"));
test("snapshot merge ignores empty module ids", () => assert.deepEqual(model.mergeExternalWidgetSnapshots({}, {moduleId: "x"}).map((x) => x.moduleId), ["x"]));
test("history serialization includes bounded snapshots", () => assert.equal(JSON.parse(model.serializeExternalWidgetHistory([{moduleId: "x"}])).version, 1));
test("history parser returns empty for malformed JSON", () => assert.deepEqual(model.parseExternalWidgetHistory("not-json"), []));
test("history parser normalizes valid snapshot list", () => assert.equal(model.parseExternalWidgetHistory('{"version":1,"snapshots":[{"moduleId":"x"}]}')[0].moduleId, "x"));

// T-4332~T-4381: external widget store state, actions, labels, privacy and diagnostics contracts.
test("store state normalizes builtin entry as directly addable", () => assert.deepEqual(model.resolveExternalWidgetStoreState({moduleId: "x", availability: "builtin"}), {moduleId: "x", status: "builtin", canAdd: true, requiresSetup: false}));
test("store state normalizes external entry as directly addable", () => assert.equal(model.resolveExternalWidgetStoreState({moduleId: "x", availability: "external"}).status, "external"));
test("store state conditional entry requires setup", () => assert.deepEqual(model.resolveExternalWidgetStoreState({moduleId: "x", availability: "conditional"}), {moduleId: "x", status: "needs-config", canAdd: false, requiresSetup: true}));
test("store state conditional configured entry is ready", () => assert.deepEqual(model.resolveExternalWidgetStoreState({moduleId: "x", availability: "conditional"}, {configured: true}), {moduleId: "x", status: "ready", canAdd: true, requiresSetup: false}));
test("store state bridge entry requires local service", () => assert.equal(model.resolveExternalWidgetStoreState({moduleId: "x", availability: "bridge"}).status, "needs-local-service"));
test("store state bridge endpoint entry is ready", () => assert.equal(model.resolveExternalWidgetStoreState({moduleId: "x", availability: "bridge"}, {endpointAvailable: true}).status, "ready"));
test("store state reference entry is never addable", () => assert.deepEqual(model.resolveExternalWidgetStoreState({moduleId: "x", availability: "reference"}), {moduleId: "x", status: "reference", canAdd: false, requiresSetup: false}));
test("store state unknown availability falls back to reference", () => assert.equal(model.resolveExternalWidgetStoreState({moduleId: "x", availability: "wat"}).status, "reference"));
test("store state preserves normalized module id", () => assert.equal(model.resolveExternalWidgetStoreState({moduleId: " x "}).moduleId, "x"));
test("store action configures missing credentials", () => assert.equal(model.resolveExternalWidgetAction({status: "needs-config", canAdd: false}), "configure"));
test("store action starts missing local service", () => assert.equal(model.resolveExternalWidgetAction({status: "needs-local-service", canAdd: false}), "start-service"));
test("store action learns reference state", () => assert.equal(model.resolveExternalWidgetAction({status: "reference", canAdd: false}), "learn-more"));
test("store action retries explicit error", () => assert.equal(model.resolveExternalWidgetAction({status: "external", canAdd: true}, {error: true}), "retry"));
test("store action retries stale health", () => assert.equal(model.resolveExternalWidgetAction({status: "external", canAdd: true}, {health: "stale"}), "retry"));
test("store action retries error health", () => assert.equal(model.resolveExternalWidgetAction({status: "external", canAdd: true}, {health: "error"}), "retry"));
test("store action adds healthy selectable state", () => assert.equal(model.resolveExternalWidgetAction({status: "external", canAdd: true}, {health: "healthy"}), "add"));
test("store action learns non selectable state", () => assert.equal(model.resolveExternalWidgetAction({status: "external", canAdd: false}), "learn-more"));
test("store action adds unknown status when explicitly addable", () => assert.equal(model.resolveExternalWidgetAction({status: "wat", canAdd: true}), "add"));
test("status label covers external state", () => assert.equal(model.resolveExternalWidgetStatusLabel("external"), "需联网"));
test("status label covers ready state", () => assert.equal(model.resolveExternalWidgetStatusLabel("ready"), "已就绪"));
test("status label covers config state", () => assert.equal(model.resolveExternalWidgetStatusLabel("needs-config"), "需要配置"));
test("status label covers local service state", () => assert.equal(model.resolveExternalWidgetStatusLabel("needs-local-service"), "需要本机服务"));
test("status label covers reference state", () => assert.equal(model.resolveExternalWidgetStatusLabel("reference"), "仅供参考"));
test("status label covers unavailable state", () => assert.equal(model.resolveExternalWidgetStatusLabel("unavailable"), "暂不可用"));
test("status label falls back for empty state", () => assert.equal(model.resolveExternalWidgetStatusLabel(""), "状态未知"));
test("described state exposes healthy add action", () => { const state = model.describeExternalWidgetStoreState({moduleId: "x", availability: "external"}, {health: "healthy"}); assert.deepEqual({status: state.status, action: state.action, canRetry: state.canRetry}, {status: "external", action: "add", canRetry: false}); });
test("described state exposes stale retry action", () => { const state = model.describeExternalWidgetStoreState({moduleId: "x", availability: "external"}, {health: "stale"}); assert.deepEqual({status: state.status, action: state.action, canRetry: state.canRetry}, {status: "external", action: "retry", canRetry: true}); });
test("described state exposes error retry action", () => assert.equal(model.describeExternalWidgetStoreState({moduleId: "x", availability: "external"}, {health: "error"}).action, "retry"));
test("described offline external state becomes unavailable", () => { const state = model.describeExternalWidgetStoreState({moduleId: "x", availability: "external"}, {health: "offline"}); assert.deepEqual({status: state.status, label: state.label, canRetry: state.canRetry}, {status: "unavailable", label: "暂不可用", canRetry: true}); });
test("described offline builtin state keeps builtin status", () => assert.equal(model.describeExternalWidgetStoreState({moduleId: "x", availability: "builtin"}, {health: "offline"}).status, "builtin"));
test("described state sanitizes diagnostic reason", () => assert.equal(model.describeExternalWidgetStoreState({moduleId: "x"}, {reason: "bad<> reason"}).reason, "bad reason"));
test("described state defaults unknown health", () => assert.equal(model.describeExternalWidgetStoreState({moduleId: "x"}).health, "unknown"));
test("described conditional state keeps configure precedence", () => { const state = model.describeExternalWidgetStoreState({moduleId: "x", availability: "conditional"}, {health: "stale"}); assert.deepEqual({status: state.status, action: state.action, requiresSetup: state.requiresSetup}, {status: "needs-config", action: "configure", requiresSetup: true}); });
test("described bridge state keeps start-service precedence", () => assert.equal(model.describeExternalWidgetStoreState({moduleId: "x", availability: "bridge"}, {health: "error"}).action, "start-service"));
test("selectable state accepts builtin", () => assert.equal(model.isExternalWidgetSelectable({status: "builtin", canAdd: true}), true));
test("selectable state accepts external", () => assert.equal(model.isExternalWidgetSelectable({status: "external", canAdd: true}), true));
test("selectable state accepts ready", () => assert.equal(model.isExternalWidgetSelectable({status: "ready", canAdd: true}), true));
test("selectable state rejects needs config", () => assert.equal(model.isExternalWidgetSelectable({status: "needs-config", canAdd: false}), false));
test("selectable state rejects reference even if addable", () => assert.equal(model.isExternalWidgetSelectable({status: "reference", canAdd: true}), false));
test("selectable state rejects unavailable even if addable", () => assert.equal(model.isExternalWidgetSelectable({status: "unavailable", canAdd: true}), false));
test("selectable state rejects null", () => assert.equal(model.isExternalWidgetSelectable(null), false));
test("state summary counts selectable items", () => assert.equal(model.summarizeExternalWidgetStates([{status: "external", canAdd: true}, {status: "reference", canAdd: false}]).selectable, 1));
test("state summary counts setup items", () => assert.equal(model.summarizeExternalWidgetStates([{status: "needs-config", requiresSetup: true}]).needsSetup, 1));
test("state summary counts unavailable items", () => assert.equal(model.summarizeExternalWidgetStates([{status: "unavailable"}]).unavailable, 1));
test("state summary counts reference items", () => assert.equal(model.summarizeExternalWidgetStates([{status: "reference"}]).reference, 1));
test("state summary counts healthy items", () => assert.equal(model.summarizeExternalWidgetStates([{health: "healthy"}]).healthy, 1));
test("state summary counts all degraded health values", () => assert.equal(model.summarizeExternalWidgetStates([{health: "error"}, {health: "stale"}, {health: "offline"}]).degraded, 3));
test("state summary ignores primitive values", () => assert.equal(model.summarizeExternalWidgetStates(["bad", 1, null]).total, 0));
test("guide link uses default document", () => assert.equal(model.buildExternalWidgetGuideLink("weather"), "docs/component-store-guide.md#weather"));
test("guide link sanitizes mixed-case anchor", () => assert.equal(model.buildExternalWidgetGuideLink("weather_01"), "docs/component-store-guide.md#weather01"));
test("guide link strips query and fragment", () => assert.equal(model.buildExternalWidgetGuideLink("x", "guide.md?raw=1#old"), "guide.md#x"));
test("guide link returns empty for empty base", () => assert.equal(model.buildExternalWidgetGuideLink("x", ""), ""));
test("guide link returns cleaned base when module empty", () => assert.equal(model.buildExternalWidgetGuideLink("", "guide.md?raw=1"), "guide.md"));
test("privacy level accepts none", () => assert.equal(model.resolveExternalWidgetPrivacyLevel("none"), "none"));
test("privacy level accepts endpoint-only", () => assert.equal(model.resolveExternalWidgetPrivacyLevel("endpoint-only"), "endpoint-only"));
test("privacy level accepts preferences-only", () => assert.equal(model.resolveExternalWidgetPrivacyLevel("preferences-only"), "preferences-only"));
